const hour = $now.setZone('America/Fortaleza').hour;
let contexto = '';

if (hour === 7 || hour === 8) {
  contexto = 'Faltam 5 minutos para os Estudos Técnicos (08:00 - 09:15). Lembre-se: o Augusto é INICIANTE absoluto em ferramentas técnicas, APIs e Postman. Apresente o tema do zero com extrema simplicidade, explicando o que é a ferramenta em 1 frase e dando o primeiro clique sem barreiras.';
} else if (hour === 9) {
  contexto = 'Faltam 5 minutos para o Treino de Musculação (09:30 - 11:30). Incentive a deixar as telas de lado, focar na hidratação e no cuidado com o corpo.';
} else if (hour === 15) {
  contexto = 'Projetos Práticos e Portfólio (15:30 - 17:30). Guie de forma simples e visual no n8n, mostrando qual nó abrir ou testar.';
} else if (hour === 17) {
  contexto = 'Mercado e Prospecção de Vagas CX/Suporte N2/N3 (17:30 - 19:00). Oriente a abrir o LinkedIn Jobs e buscar termos básicos de suporte e CX.';
} else if (hour === 18 || hour === 19) {
  contexto = 'Expansão Intelectual (19:00 - 20:00). Indique leitura básica, módulo introdutório ou talk acessível no YouTube.';
} else {
  contexto = 'Check-in amigável e acolhedor sobre o dia.';
}

return [{ json: { contexto, hour } }];
